import { getContext, setContext } from 'svelte'
import type { StoreCart } from '@medusajs/types'
import type { CartLine } from './types.js'

export type CartContext = {
	readonly cart: StoreCart | null | undefined
	readonly loading: boolean
	readonly error: unknown
	readonly count: number
	readonly lineCount: number
	readonly subtotal: number | undefined
	readonly pending: boolean
	readonly checkoutUrl: string
	lineHref: (item: CartLine) => string
	updateItem: (itemId: string, quantity: number) => Promise<void>
	removeItem: (itemId: string) => Promise<void>
}
export type CartLineContext = { readonly item: CartLine }

export type CartSheetContext = {
	closeOnClick: (node: HTMLElement) => () => void
}

const CART = Symbol('cart')
const LINE = Symbol('cart-line')
const SHEET = Symbol('cart-sheet')

export function setCartContext(ctx: CartContext) {
	setContext(CART, ctx)
}

export function getCartContext(): CartContext {
	const ctx = getContext<CartContext>(CART)
	if (!ctx) throw new Error('Cart.* must be used within <Cart.Root>')
	return ctx
}

export function getCartContextOptional(): CartContext | null {
	return getContext<CartContext>(CART) ?? null
}

export function setCartSheetContext(ctx: CartSheetContext) {
	setContext(SHEET, ctx)
}

// Absent when the cart parts render outside <Cart.Sheet> (an inline /cart page), which is why
// callers spread it as a falsy attachment rather than branching.
export function getCartSheetContextOptional(): CartSheetContext | null {
	return getContext<CartSheetContext>(SHEET) ?? null
}

export function setCartLineContext(ctx: CartLineContext) {
	setContext(LINE, ctx)
}

export function getCartLineContext(): CartLineContext {
	const ctx = getContext<CartLineContext>(LINE)
	if (!ctx) throw new Error('Cart line parts must be used within <Cart.Item>')
	return ctx
}

import type { StoreCart } from '@medusajs/types'
import type { CartLine, LineHrefFn } from './types.js'

export function totalQuantity(cart: StoreCart | null | undefined): number {
	return (cart?.items ?? []).reduce((n, li) => n + (li.quantity ?? 0), 0)
}

export function lineCount(cart: StoreCart | null | undefined): number {
	return cart?.items?.length ?? 0
}

export function subtotal(cart: StoreCart | null | undefined): number | undefined {
	return (cart as { item_subtotal?: number } | null | undefined)?.item_subtotal ?? undefined
}

export const defaultLineHref: LineHrefFn = (item: CartLine) => `/product/${item.product_handle}${item.variant_id ? `?variant=${item.variant_id}` : ''}`

// Medusa returns amounts in major units. `locale` is pinned (default 'en-US') so server + client
// render identically (avoids a hydration mismatch from host-locale differences).
export function formatPrice(amount: number | null | undefined, currencyCode: string | null | undefined, locale = 'en-US'): string {
	if (amount == null || !currencyCode) return ''
	return new Intl.NumberFormat(locale, {
		style: 'currency',
		currency: currencyCode.toUpperCase()
	}).format(amount)
}

import Root from './cart.svelte'
import Trigger from './cart-trigger.svelte'
import Badge from './cart-badge.svelte'
import Sheet from './cart-sheet.svelte'
import Content from './cart-content.svelte'
import Header from './cart-header.svelte'
import Items from './cart-items.svelte'
import Item from './cart-item.svelte'
import Image from './cart-image.svelte'
import Title from './cart-title.svelte'
import Price from './cart-price.svelte'
import ItemSubtotal from './cart-item-subtotal.svelte'
import Quantity from './cart-quantity.svelte'
import Remove from './cart-remove.svelte'
import Subtotal from './cart-subtotal.svelte'
import Checkout from './cart-checkout.svelte'
import Empty from './cart-empty.svelte'

// `Trigger`, `Content` and `Header` are the drawer's sheet parts, flattened onto this barrel so a
// consumer never has to reach for the raw shadcn `Sheet` alongside `Cart`:
//   <Cart.Root>
//     <Cart.Sheet>
//       <Cart.Trigger />
//       <Cart.Content>
//         <Cart.Header />
//         <Cart.Items>…</Cart.Items>
//       </Cart.Content>
//     </Cart.Sheet>
//   </Cart.Root>
// `Cart.Sheet` is optional — the same parts render inline on a /cart page without it.
export { Root, Trigger, Badge, Sheet, Content, Header, Items, Item, Image, Title, Price, ItemSubtotal, Quantity, Remove, Subtotal, Checkout, Empty }
export {
	getCartContext,
	getCartContextOptional,
	setCartContext,
	getCartLineContext,
	setCartLineContext,
	getCartSheetContextOptional,
	setCartSheetContext
} from './ctx.svelte.js'
export type { CartContext, CartLineContext, CartSheetContext } from './ctx.svelte.js'
export type { CartLine, CartQuery, LineHrefFn } from './types.js'
export { formatPrice } from './format-price.js'
export * as logic from './cart-logic.js'
